150	      const interval = (formData.get("interval") as string) || "monthly";
151	      const plan = getPlan(planId);
152	
153	      if (plan.price === 0) {
154	        // Downgrade to free — cancel existing Shopify subscription if any
155	        try {
156	          await cancelSubscription(billingContext);
157	        } catch {
158	          // No active subscription to cancel — that's fine
159	        }
160	        await db.subscription.upsert({
161	          where: { shop },
162	          update: { planId: "free", status: "active", billingInterval: "monthly", shopifySubscriptionId: null },
163	          create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
164	        });
165	        return { ok: true, message: "Switched to Free plan" };
166	      }
167	
168	      // Create Shopify subscription — returns a confirmation URL
169	      const billingInterval = interval === "annual" ? "annual" as const : "monthly" as const;
170	      const { confirmationUrl } = await createSubscription(
