1	// ---------------------------------------------------------------------------
2	// In-memory sliding window rate limiter for public API endpoints
3	// ---------------------------------------------------------------------------
4	
5	interface RateLimitEntry {
6	  count: number;
7	  resetAt: number;
8	}
9	
10	const store = new Map<string, RateLimitEntry>();
11	
12	// Cleanup stale entries every 5 minutes to prevent memory leaks
13	const CLEANUP_INTERVAL = 5 * 60 * 1000;
14	let lastCleanup = Date.now();
15	
16	function cleanup(): void {
17	  const now = Date.now();
18	  if (now - lastCleanup < CLEANUP_INTERVAL) return;
19	  lastCleanup = now;
20	  for (const [key, entry] of store) {
21	    if (entry.resetAt <= now) {
22	      store.delete(key);
23	    }
24	  }
25	}
26	
27	/**
28	 * Check rate limit for a given key (typically "endpoint:shop").
29	 * Returns null if under limit, or a Response (429) if over limit.
30	 */
31	export function checkRateLimit(
32	  key: string,
33	  maxRequests: number,
34	  windowMs: number = 60_000,
35	): Response | null {
36	  cleanup();
37	
38	  const now = Date.now();
39	  const entry = store.get(key);
40	
41	  if (!entry || entry.resetAt <= now) {
42	    store.set(key, { count: 1, resetAt: now + windowMs });
43	    return null;
44	  }
45	
46	  entry.count++;
47	
48	  if (entry.count > maxRequests) {
49	    const retryAfter = Math.ceil((entry.resetAt - now) / 1000);
50	    return Response.json(
51	      { error: "Too many requests. Please try again later." },
52	      {
53	        status: 429,
54	        headers: {
55	          "Access-Control-Allow-Origin": "*",
56	          "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
57	          "Access-Control-Allow-Headers": "Content-Type",
58	          "Retry-After": String(retryAfter),
59	        },
60	      },
61	    );
62	  }
63	
64	  return null;
65	}
